const $=s=>document.querySelector(s);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const cinematicCanvas=$('#cinematic-canvas'), cinematicContext=cinematicCanvas?.getContext('2d');
const cinematicParticles=Array.from({length:90},(_,i)=>({x:(i*0.618)%1,y:(i*0.371)%1,z:.2+((i*0.173)%1),drift:i*.71,size:.4+((i*0.83)%1)*1.6}));
function resizeCinematic(){if(!cinematicCanvas)return;const d=Math.min(devicePixelRatio||1,1.5);cinematicCanvas.width=innerWidth*d;cinematicCanvas.height=innerHeight*d;cinematicCanvas.style.width=innerWidth+'px';cinematicCanvas.style.height=innerHeight+'px';cinematicContext.setTransform(d,0,0,d,0,0)}
function renderCinematic(t=0){if(!cinematicContext)return;const w=innerWidth,h=innerHeight;cinematicContext.clearRect(0,0,w,h);cinematicParticles.forEach((p,i)=>{const depth=p.z, x=(p.x*w+Math.sin(t*.00025+p.drift)*28+scrollY*(p.z-.5)*.12)%w, y=(p.y*h+Math.cos(t*.0002+p.drift)*18+scrollY*p.z*.035)%(h+20);cinematicContext.globalAlpha=(.08+depth*.3)*(reduced?1:.65+.35*Math.sin(t*.001+p.drift));cinematicContext.fillStyle=i%5===0?'#f2b56f':'#b9d9d2';cinematicContext.beginPath();cinematicContext.arc(x<0?x+w:x,y,p.size*depth,0,Math.PI*2);cinematicContext.fill()});requestAnimationFrame(renderCinematic)}
resizeCinematic();renderCinematic();addEventListener('resize',resizeCinematic);
