let audioContext,ambience=[],sound=false;
function audio(){return audioContext||(audioContext=new AudioContext())}
function chime(){if(!sound)return;const c=audio();c.resume();const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(660,c.currentTime);o.frequency.exponentialRampToValueAtTime(880,c.currentTime+.09);g.gain.setValueAtTime(.018,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.18);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.2)}
$('#sound-toggle').onclick=()=>{sound=!sound;$('#sound-toggle').setAttribute('aria-pressed',String(sound));$('#sound-toggle').setAttribute('aria-label','Turn sound effects '+(sound?'off':'on'));$('#sound-toggle img').src=icon(sound?'volume-up':'volume-mute');chime()};
$('#music-toggle').onclick=()=>{const playing=!ambience.length;if(playing){const c=audio();c.resume();[130.81,196,261.63].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;o.detune.value=i*2;g.gain.setValueAtTime(0,c.currentTime);g.gain.linearRampToValueAtTime(.008,c.currentTime+2);o.connect(g).connect(c.destination);o.start();ambience.push({o,g})})}else{const c=audio();ambience.forEach(({o,g})=>{g.gain.linearRampToValueAtTime(0,c.currentTime+.5);o.stop(c.currentTime+.6)});ambience=[]}$('#music-toggle').setAttribute('aria-pressed',String(playing));$('#music-toggle .music-text').textContent=playing?'Pause ambience':'Play ambience';$('#music-toggle img').src=icon(playing?'pause-fill':'play-fill')};
