const cases={health:{tag:'YOSEMITE MD SOLUTION / MAR–JUN 2026',title:'Less waiting. More care.',context:'Healthcare workflows were slowed by manual claims processing, routine call hand-offs and a 14-second patient records screen.',build:'Built agentic RCM automation, voice agents using speech-to-text and text-to-speech, and SOAP note transcription. Traced three redundant database round trips through a microservice chain to an encrypted table of 40,000+ patient records and consolidated them into one query path.',result:'Claims processed 6× faster than the manual workflow. Patient records loaded in 600ms and stayed under 1 second at peak. The transcription service reduced corrections before doctors signed off.'},speech:{tag:'AAIZEL INTERNATIONAL TECHNOLOGIES / AUG–DEC 2025',title:'Many languages. One fluent system.',context:'A production speech system needed to handle several Indian regional languages with low latency.',build:'Trained and deployed multilingual speech-to-text, with automated retraining using MLflow and Kubernetes and predictions served through FastAPI REST APIs. Also built MQTT/Kafka radiosonde parsing, SCADA validation and real-time face detection with liveness checks.',result:'Speech-to-text returned results in under a second across several Indian regional languages.'},vision:{tag:'SOFLY INNOVATION / AUG 2024–JUL 2025',title:'A different point of view.',context:'Drone imagery applications needed more efficient processing and lower inference latency on edge devices.',build:'Reworked preprocessing and feature extraction in Python and TensorFlow and compressed models for edge deployment. Built conversational AI features using LangChain and LlamaIndex and refined retrieval and prompting.',result:'Preprocessing and feature extraction ran 30% faster. Chatbot answer accuracy improved by roughly 25%.'}};
