function localAsk(q){q=q.trim();if(!q)return;const answer=$('#answer');answer.hidden=false;const close=document.createElement('button');close.textContent='Close';close.type='button';close.addEventListener('click',()=>answer.hidden=true);const p=document.createElement('span');const lower=q.toLowerCase();let a;if(/skill|stack|tool|tech|python/.test(lower))a='My toolkit spans Python, PyTorch, TensorFlow, LLMs, RAG, LangChain, LlamaIndex and agentic AI. I deploy with MLflow, Kubernetes and Docker across AWS, Azure and GCP, and build products using FastAPI, Django, Node.js, React and Flutter.';else if(/project|built|work|impact|claim|health/.test(lower))a='At Yosemite MD Solution, I built claims automation that was 6× faster and reduced a patient records load from 14 seconds to 600ms. At Aaizel, I deployed sub-second multilingual speech-to-text. At Sofly, I built drone vision systems and RAG-powered conversational AI. Open a case study below for the details.';else if(/experience|career|journey|company|role/.test(lower))a='I’ve shipped products since founding Hostsac in 2019. I co-founded drone startup Aerwolf in 2023, then worked in AI at Sofly Innovation, Aaizel International Technologies and Yosemite MD Solution, alongside independent full-stack contracts. Explore the timeline for dates and responsibilities.';else if(/educat|degree|university|study|certif/.test(lower))a='I completed B.E. Computer Science & Engineering with Honours in AI and ML at Chandigarh University (2021–2025). My certifications include Anthropic AI Fluency for Builders, AI Fluency Framework and Foundations (2026), and Packt Raspberry Pi and Arduino (2025).';else if(/contact|hire|email|location|remote|relocat|available/.test(lower))a='I’m based in Mohali, Punjab, India and open to remote work and relocation. Reach me at shuklaabhay075@gmail.com or on LinkedIn at linkedin.com/in/abhays02.';else if(/name|who|about|introduc/.test(lower))a='I’m Abhay Shukla, an AI engineer and full-stack developer. I build LLM and RAG systems, agentic automation, computer vision and multilingual speech systems, along with the APIs and MLOps infrastructure they run on.';else a='This guide answers from my resume. Try asking about my experience, projects, skills, education or how to contact me. For something more specific, email shuklaabhay075@gmail.com.';p.textContent=a;const note=document.createElement('small');note.textContent='RESUME GUIDE · LOCAL ANSWERS';note.style.cssText='display:block;margin-top:14px;font-size:8px;letter-spacing:1.5px;color:#9fb4c9';answer.replaceChildren(close,p,note)}$('#ask-form').addEventListener('submit',e=>{e.preventDefault();ask($('#question').value)});document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{$('#question').value=b.dataset.question;ask(b.dataset.question)}));document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#answer').hidden=true});
