let aiEnabled=false,turnstileToken='',turnstileWidget=null,requestNumber=0;const verification=document.querySelector('#ai-verification');
siteSettings.then(s=>s.backend?fetch(new URL('api/status',document.baseURI)):Promise.reject()).then(r=>r.ok?r.json():Promise.reject()).then(s=>{aiEnabled=s.aiEnabled;$('#question').placeholder=aiEnabled?'Ask my AI guide about my work…':'Ask about my experience, projects, or skills…';if(s.turnstileSiteKey){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=()=>{turnstileWidget=window.turnstile.render(verification,{sitekey:s.turnstileSiteKey,theme:'dark',callback:t=>{turnstileToken=t},'expired-callback':()=>{turnstileToken=''}})};script.onerror=()=>{aiEnabled=false};document.head.append(script)}}).catch(()=>{});
async function ask(q){q=q.trim();if(!q)return;if(!aiEnabled){localAsk(q);return}const current=++requestNumber;const a=$('#answer');a.hidden=false;const close=document.createElement('button');close.textContent='Close';close.type='button';close.onclick=()=>a.hidden=true;const text=document.createElement('span');text.textContent='Thinking through your question…';a.replaceChildren(close,text);a.setAttribute('aria-busy','true');const button=$('#ask-form button');button.disabled=true;try{const r=await fetch(new URL('api/chat',document.baseURI),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,turnstileToken}),signal:AbortSignal.timeout(30000)});const data=await r.json();if(current!==requestNumber)return;if(!r.ok){text.textContent=data.error||'The AI guide is unavailable.';const fallback=document.createElement('button');fallback.textContent='Use resume guide';fallback.onclick=()=>localAsk(q);a.append(fallback);return}text.textContent=data.answer;const note=document.createElement('small');note.textContent='AI GUIDE · GROUNDED IN RESUME & PUBLIC PROJECTS';note.style.cssText='display:block;font-size:8px;letter-spacing:1px;margin-top:14px;color:#9fb4c9';a.append(note)}catch{if(current!==requestNumber)return;text.textContent='The AI guide is unavailable. ';const fallback=document.createElement('button');fallback.textContent='Use resume guide';fallback.onclick=()=>localAsk(q);a.append(fallback)}finally{button.disabled=false;a.setAttribute('aria-busy','false');turnstileToken='';if(turnstileWidget!==null)window.turnstile.reset(turnstileWidget)}}

