function chooseStop(i){activeStop=i;const s=stops[i];$('#journey-card').innerHTML=`<small><span>${s.year}</span><span>${String(i+1).padStart(2,'0')} / 07</span></small><h3>${s.title}</h3><p>${s.body}</p><span class="role-tag">${s.name} · ${s.role}</span>`;[...pins.children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',String(i===j))});[...dots.children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',String(i===j))});drawRoute()}
function drawRoute(){const canvas=$('#journey-route'),world=$('#map-world'),w=world.clientWidth,h=world.clientHeight;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;const c=canvas.getContext('2d');c.scale(devicePixelRatio,devicePixelRatio);c.lineWidth=3;c.lineJoin='round';c.strokeStyle='#7d827b66';c.beginPath();stops.forEach((s,i)=>{const x=w*s.x/100,y=h*s.y/100-20;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke();c.strokeStyle='#f1ce6a';c.beginPath();stops.slice(0,activeStop+1).forEach((s,i)=>{const x=w*s.x/100,y=h*s.y/100-20;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()}
