function updateScroll(){const r=$('#home').getBoundingClientRect(),travel=Math.max(1,r.height-innerHeight),progress=Math.max(0,Math.min(1,-r.top/travel));document.documentElement.style.setProperty('--scroll-progress',String(progress));const allSections=[...document.querySelectorAll('main > section')];const total=Math.max(1,document.documentElement.scrollHeight-innerHeight);const globalProgress=Math.max(0,Math.min(1,scrollY/total));document.documentElement.style.setProperty('--global-progress',String(globalProgress));const chapter=Math.min(7,Math.max(1,Math.floor(globalProgress*7)+1));document.querySelector('.scene-rail-count')?.replaceChildren(document.createTextNode(String(chapter).padStart(2,'0')+' / 07'));allSections.forEach((section,index)=>section.classList.toggle('scene-active',section.getBoundingClientRect().top<innerHeight*.62&&section.getBoundingClientRect().bottom>innerHeight*.28));if(!reduced){const opacity=Math.max(0,1-progress*2.7);$('.valley-copy').style.opacity=opacity;$('.valley-copy').style.transform=`translateY(${-progress*65}px)`;$('.landscape').style.transform=`scale(${1+progress*.16})`;$('.world-places').style.opacity=Math.max(0,1-progress*1.5)}document.body.classList.toggle('past-hero',r.bottom<innerHeight*.4);const j=$('#journey').getBoundingClientRect();if(!reduced&&j.top<0&&j.bottom>innerHeight&&Date.now()>manualStopUntil){const n=Math.min(6,Math.floor(Math.max(0,-j.top/(j.height-innerHeight))*7));if(n!==activeStop)chooseStop(n)}let current=0;navSections.forEach((s,i)=>{if(s.getBoundingClientRect().top<innerHeight*.45)current=i});navLinks.forEach((a,i)=>{a.classList.toggle('active',i===current);if(i===current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
